import test from 'node:test';
import assert from 'node:assert/strict';
import { roundMoney } from '../src/money.mjs';

test('roundMoney rounds decimal boundaries half away from zero', () => {
  for (const [input, expected] of [
    [1.005, 1.01], [2.675, 2.68], [4.015, 4.02],
    [10.075, 10.08], [0.005, 0.01], [12.345, 12.35],
    [1.0049, 1], [1.0051, 1.01], [9.995, 10],
  ]) {
    assert.equal(roundMoney(input), expected);
    assert.equal(roundMoney(-input), -expected);
  }
});

test('roundMoney normalizes zero, including scientific notation', () => {
  for (const input of [0, -0, 1e-7, -1e-7, Number.MIN_VALUE, -Number.MIN_VALUE]) {
    assert.equal(roundMoney(input), 0);
    assert.equal(Object.is(roundMoney(input), -0), false);
  }
});

test('roundMoney preserves large finite values without overflow', () => {
  for (const input of [Number.MAX_VALUE, -Number.MAX_VALUE, 1e21, -1e21, 1.2345e100]) {
    assert.equal(roundMoney(input), input);
    assert.equal(Number.isFinite(roundMoney(input)), true);
  }
});

test('roundMoney retains finite-number input validation', () => {
  for (const input of [NaN, Infinity, -Infinity, '12.345', null, undefined, 1n, {}]) {
    assert.throws(() => roundMoney(input), {
      name: 'TypeError', message: 'finite number required',
    });
  }
});
