import assert from 'node:assert/strict';
import { roundMoney } from './src/money.mjs';
let count = 0;
for (const [value, expected] of [[0.004999999999999999,0],[0.005,0.01],[0.005000000000000001,0.01],[0.014999999999999998,0.01],[0.015,0.02],[99.995,100],[1.234e-5,0],[1.234e20,1.234e20],[1.7976931348623155e308,1.7976931348623155e308],[Number.MAX_VALUE,Number.MAX_VALUE]]) {
 for (const sign of [1,-1]) {
  const actual = roundMoney(sign * value);
  assert.equal(actual, expected === 0 ? 0 : sign * expected);
  assert.equal(Object.is(actual,-0),false);
  assert.ok(Number.isFinite(actual));
  count++;
 }
}
console.log("'`${count} independent signed boundary checks passed`);
